package store

// The ent client is generated by `task generate` and checked in, so a normal
// build never needs the generator:
//
//	go tool ent generate ./internal/store/ent/schema \
//	    --target ./internal/store/ent \
//	    --feature sql/upsert \
//	    --header "// Code generated by ent, DO NOT EDIT."
//
// sql/upsert is required: Observe upserts by job id.
